      "most_likely_effort": 8
    },
    {
      "activity_id": "A6",
      "activity_name": "U2 Implement authentication",
      "activity_description": "Implement username/password prompt, secure credential handling (no file storage), and integration with Admin server security context.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A7",
      "activity_name": "U2 Test authentication",
      "activity_description": "Write tests for authentication flow, including failed attempts and session management.",
      "most_likely_effort": 16
