    {
      "activity_id": "A26",
      "activity_name": "U7 Evaluate and select processing library",
      "activity_description": "Evaluate Java libraries (JavaCV, FFmpeg, etc.) for Motion-JPEG decoding and facial detection; select one.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A27",
      "activity_name": "U7 Implement streaming ingestion",
      "activity_description": "Develop streaming ingestion pipeline for audio/video data with Motion-JPEG support.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A28",
      "activity_name": "U7 Integrate facial detection",
